#include <string.h>
static char g_src[] = "bcdefghij";
int f(void){char b[6]; b[0]='a'; b[1]=0; strcat(b, g_src); return b[0];}
int main(void){(void)f(); return 0;}

#include <stdlib.h>
static char *g;
__attribute__((noinline)) static void setup(void){ g = (char *)malloc(8); }
__attribute__((noinline)) static void teardown(void){ free(g); }
int f(void){ setup(); teardown(); if (g) return g[0]; return 0; }
int main(void){(void)f(); return 0;}

